    def cols(p):
        c,e,k=p[0],p[1],p[2]
        g={'t^k':t**k,'exp(-kt)':np.exp(-k*t),'t^k*sqrtP':t**k*np.sqrt(P),'t^k*P':t**k*P,'logt':np.log(t)*k}[name]
